package com.cni.report; import com.cni.casefile.InvestigationCase; import com.cni.user.AppUser; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="investigation_reports") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class InvestigationReport{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="case_id",nullable=false)private InvestigationCase investigationCase;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="author_id",nullable=false)private AppUser author;@Column(nullable=false,length=240)private String title;@Column(columnDefinition="TEXT")private String content;@Column(nullable=false,length=24)private String status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;}
